import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        final int MAX_SIZE = 2345678;
        Scanner sc = new Scanner(System.in);

        int total_real = sc.nextInt();
        int max_k = sc.nextInt();

        double[] probabilities_real = new double[123];
        double[] probabilities = new double[123];
        double[] dynamic_prog = new double[MAX_SIZE];
        double[] results = new double[123];
        int[] indices = new int[123];
        int[] bit_counts = new int[MAX_SIZE];

        int valid_count = 0;
        for (int i = 0; i < total_real; i++) {
            probabilities_real[i] = sc.nextDouble();
            if (probabilities_real[i] > 1e-4) {
                indices[valid_count] = i;
                probabilities[valid_count] = probabilities_real[i];
                valid_count++;
            }
        }

        max_k = Math.min(max_k, valid_count);

        for (int mask = 1; mask < (1 << valid_count); mask++) {
            bit_counts[mask] = bit_counts[mask & (mask - 1)] + 1;
        }

        for (int mask = 0; mask < (1 << valid_count); mask++) {
            dynamic_prog[mask] = 0.0;
        }

        for (int i = 0; i < total_real; i++) {
            results[i] = 0.0;
        }

        dynamic_prog[0] = 1.0;

        for (int mask = 0; mask < (1 << valid_count); mask++) {
            if (bit_counts[mask] == max_k) {
                for (int j = 0; j < valid_count; j++) {
                    if ((mask & (1 << j)) != 0) {
                        results[indices[j]] += dynamic_prog[mask];
                    }
                }
                continue;
            }
            double total_prob = 0;
            for (int j = 0; j < valid_count; j++) {
                if ((mask & (1 << j)) != 0) continue;
                total_prob += probabilities[j];
            }
            double q_value = dynamic_prog[mask] / total_prob;
            for (int j = 0; j < valid_count; j++) {
                if ((mask & (1 << j)) != 0) continue;
                dynamic_prog[mask | (1 << j)] += probabilities[j] * q_value;
            }
        }

        for (int i = 0; i < total_real; i++) {
            if (i > 0) System.out.print(" ");
            System.out.printf("%.17f", results[i]);
        }
        System.out.println();
        sc.close();
    }
}
